# The journey emails that existed before were never sent: each keeps its place on the nearest new track, switched
# off until a Super Admin rewrites and turns it on.
OLD_TRIGGERS = {
    "lead_created": "screened",
    "consult_booked": "consulted",
    "payment_failed": "payment_failed",
    "review_due": "ongoing",
    "shipment_dispatched": "early",
}


def move_old_journeys(apps, schema_editor):
    EmailJourney = apps.get_model("care", "EmailJourney")
    for journey in EmailJourney.objects.all():
        journey.trigger = OLD_TRIGGERS.get(journey.trigger, journey.trigger)
        journey.is_active = False
        journey.save(update_fields=("trigger", "is_active"))


